import React, { lazy, Suspense } from 'react';
import { BrowserRouter as Router, Routes, Route, useLocation, Navigate } from 'react-router-dom';
import { HelmetProvider } from 'react-helmet-async';
import { AppToaster } from './components/Toast';
import ProtectedRoute from './components/ProtectedRoute';
import AdminRoute from './components/AdminRoute';
import StaffRoute from './components/StaffRoute';
import RouteFallback from './components/RouteFallback';
import ErrorBoundary from './components/ErrorBoundary';
import GlobalJsonLd from './components/GlobalJsonLd';
import ScrollToTop from './components/ScrollToTop';
import SkipLink from './components/SkipLink';

import { CartProvider } from './context/CartContext';
import { AuthProvider } from './context/AuthContext';
import { WishlistProvider } from './context/WishlistContext';
import { DeliveryLocationProvider } from './context/DeliveryLocationContext';
import { StaffAuthProvider } from './context/StaffAuthContext';

const Home = lazy(() => import('./pages/Home'));
const Shop = lazy(() => import('./pages/Products'));
const ProductDetail = lazy(() => import('./pages/ProductDetail'));
const CategoryPage = lazy(() => import('./pages/CategoryPage'));
const BrandsPage = lazy(() => import('./pages/BrandsPage'));
const LegacyShopRedirect = lazy(() => import('./pages/LegacyShopRedirect'));
const LegacyProductRedirect = lazy(() => import('./pages/LegacyProductRedirect'));
const Login = lazy(() => import('./pages/Login'));
const Register = lazy(() => import('./pages/Register'));
const ForgotPassword = lazy(() => import('./pages/auth/ForgotPassword'));
const ResetPassword = lazy(() => import('./pages/auth/ResetPassword'));
const VerifyEmail = lazy(() => import('./pages/auth/VerifyEmail'));
const Cart = lazy(() => import('./pages/Cart'));
const Checkout = lazy(() => import('./pages/Checkout'));
const OrderConfirmation = lazy(() => import('./pages/OrderConfirmation'));
const AccountLayout = lazy(() => import('./pages/account/AccountLayout'));
const AccountDashboard = lazy(() => import('./pages/account/AccountDashboard'));
const MyOrders = lazy(() => import('./pages/account/MyOrders'));
const OrderDetail = lazy(() => import('./pages/account/OrderDetail'));
const Profile = lazy(() => import('./pages/account/Profile'));
const Addresses = lazy(() => import('./pages/account/Addresses'));
const AccountWishlist = lazy(() => import('./pages/account/Wishlist'));
const MyReviews = lazy(() => import('./pages/account/MyReviews'));
const Orders = lazy(() => import('./pages/Orders'));
const WishlistPage = lazy(() => import('./pages/WishlistPage'));
const Blog = lazy(() => import('./pages/Blog'));
const BlogDetailsPage = lazy(() => import('./pages/BlogDetailsPage'));
const AboutUs = lazy(() => import('./pages/AboutUs'));
const PrivacyPolicy = lazy(() => import('./pages/PrivacyPolicy'));
const ContactUs = lazy(() => import('./pages/ContactUs'));
const Faqs = lazy(() => import('./pages/Faqs'));
const TermsAndConditions = lazy(() => import('./pages/TermsAndConditions'));
const NotFound = lazy(() => import('./pages/NotFound'));
const AdminLayout = lazy(() => import('./pages/admin/AdminLayout'));
const AdminDashboard = lazy(() => import('./pages/admin/AdminDashboard'));
const AdminProducts = lazy(() => import('./pages/admin/AdminProducts'));
const AdminPlaceholder = lazy(() => import('./pages/admin/AdminPlaceholder'));
const ProductForm = lazy(() => import('./pages/admin/ProductForm'));
const AdminOrders = lazy(() => import('./pages/admin/AdminOrders'));
const AdminOrderDetail = lazy(() => import('./pages/admin/AdminOrderDetail'));
const AdminCategories = lazy(() => import('./pages/admin/AdminCategories'));
const AdminCustomers = lazy(() => import('./pages/admin/AdminCustomers'));
const AdminAnalytics = lazy(() => import('./pages/admin/AdminAnalytics'));
const AdminStoreSettings = lazy(() => import('./pages/admin/AdminStoreSettings'));
const AdminCoupons = lazy(() => import('./pages/admin/AdminCoupons'));
const AdminFraud = lazy(() => import('./pages/admin/AdminFraud'));
const StaffManagement = lazy(() => import('./pages/admin/StaffManagement'));
const StaffLayout = lazy(() => import('./pages/staff/StaffLayout'));
const StaffDashboard = lazy(() => import('./pages/staff/StaffDashboard'));
const StaffProducts = lazy(() => import('./pages/staff/StaffProducts'));
const StaffCategories = lazy(() => import('./pages/staff/StaffCategories'));
const StaffOrders = lazy(() => import('./pages/staff/StaffOrders'));
const Navbar = lazy(() => import('./components/Navbar'));
const HomeCategoryStrip = lazy(() => import('./components/HomeCategoryStrip'));
const Footer = lazy(() => import('./components/Footer'));
const DeferredChatbot = lazy(() => import('./components/DeferredChatbot'));

function AppShell() {
  const location = useLocation();
  const isAdmin = location.pathname.startsWith('/admin');
  return (
    <div className="App">
      {!isAdmin && <GlobalJsonLd />}
      <AppToaster />
      {!isAdmin && <SkipLink />}
      {!isAdmin && (
        <Suspense fallback={<header className="site-chrome-placeholder site-chrome-placeholder--header" aria-hidden />}>
          <Navbar />
        </Suspense>
      )}
      {!isAdmin && (
        <Suspense fallback={<div className="site-chrome-placeholder site-chrome-placeholder--category-strip" aria-hidden />}>
          <HomeCategoryStrip />
        </Suspense>
      )}
      {!isAdmin && (
        <Suspense fallback={null}>
          <DeferredChatbot />
        </Suspense>
      )}
      <main
        id="main-content"
        tabIndex={-1}
        className={isAdmin ? 'main-content main-content--admin' : 'main-content'}
      >
        <ErrorBoundary>
          <Suspense fallback={<RouteFallback />}>
            <Routes>

                      <Route path="/" element={<Home />} />
                      <Route path="/home" element={<Home />} />
                      <Route path="/shop/category/:categorySlug" element={<Shop />} />
                      <Route path="/brand/:brandSlug" element={<Shop />} />
                      <Route path="/shop" element={<Shop />} />
                      <Route path="/shop/:slug" element={<ProductDetail />} />
                      <Route path="/category/:slug" element={<CategoryPage />} />
                      <Route path="/brands" element={<BrandsPage />} />

                      <Route path="/login" element={<Login />} />
                      <Route path="/register" element={<Register />} />
                      <Route path="/forgot-password" element={<ForgotPassword />} />
                      <Route path="/reset-password/:token" element={<ResetPassword />} />
                      <Route path="/verify-email/:token" element={<VerifyEmail />} />

                      <Route path="/products" element={<LegacyShopRedirect />} />
                      <Route path="/product/:slug" element={<LegacyProductRedirect />} />

                      <Route path="/cart" element={<Cart />} />
                      <Route path="/checkout" element={<Checkout />} />
                      <Route path="/order-confirmation/:id" element={<OrderConfirmation />} />

                      <Route
                        path="/account"
                        element={
                          <ProtectedRoute>
                            <AccountLayout />
                          </ProtectedRoute>
                        }
                      >
                        <Route index element={<AccountDashboard />} />
                        <Route path="orders" element={<MyOrders />} />
                        <Route path="orders/:id" element={<OrderDetail />} />
                        <Route path="profile" element={<Profile />} />
                        <Route path="addresses" element={<Addresses />} />
                        <Route path="wishlist" element={<AccountWishlist />} />
                        <Route path="reviews" element={<MyReviews />} />
                      </Route>

                      <Route
                        path="/orders"
                        element={
                          <ProtectedRoute>
                            <Orders />
                          </ProtectedRoute>
                        }
                      />
                      <Route path="/wishlist" element={<WishlistPage />} />
                      <Route path="/blog" element={<Blog />} />
                      <Route path="/blog/:slug" element={<BlogDetailsPage />} />
                      <Route path="/about-us" element={<AboutUs />} />
                      <Route path="/privacy-policy" element={<PrivacyPolicy />} />
                      <Route path="/contact-us" element={<ContactUs />} />
                      <Route path="/faqs" element={<Faqs />} />
                      <Route path="/terms-and-conditions" element={<TermsAndConditions />} />

                      <Route
                        path="/staff"
                        element={
                          <StaffRoute>
                            <StaffLayout />
                          </StaffRoute>
                        }
                      >
                        <Route index element={<Navigate to="dashboard" replace />} />
                        <Route
                          path="dashboard"
                          element={
                            <StaffRoute permission="viewAnalytics">
                              <StaffDashboard />
                            </StaffRoute>
                          }
                        />
                        <Route
                          path="products"
                          element={
                            <StaffRoute permission="manageProducts">
                              <StaffProducts />
                            </StaffRoute>
                          }
                        />
                        <Route
                          path="products/new"
                          element={
                            <StaffRoute permission="manageProducts">
                              <ProductForm />
                            </StaffRoute>
                          }
                        />
                        <Route
                          path="products/:id/edit"
                          element={
                            <StaffRoute permission="manageProducts">
                              <ProductForm />
                            </StaffRoute>
                          }
                        />
                        <Route
                          path="categories"
                          element={
                            <StaffRoute permission="manageCategories">
                              <StaffCategories />
                            </StaffRoute>
                          }
                        />
                        <Route
                          path="orders"
                          element={
                            <StaffRoute permission="manageOrders">
                              <StaffOrders />
                            </StaffRoute>
                          }
                        />
                        <Route
                          path="orders/:id"
                          element={
                            <StaffRoute permission="manageOrders">
                              <AdminOrderDetail basePath="/staff" />
                            </StaffRoute>
                          }
                        />
                        <Route
                          path="customers"
                          element={
                            <StaffRoute permission="manageCustomers">
                              <AdminCustomers />
                            </StaffRoute>
                          }
                        />
                        <Route
                          path="analytics"
                          element={
                            <StaffRoute permission="viewAnalytics">
                              <AdminAnalytics />
                            </StaffRoute>
                          }
                        />
                        <Route
                          path="coupons"
                          element={
                            <StaffRoute permission="manageCoupons">
                              <AdminCoupons />
                            </StaffRoute>
                          }
                        />
                        <Route
                          path="blog"
                          element={
                            <StaffRoute permission="manageBlog">
                              <AdminPlaceholder title="Blog management" description="Connect your staff blog management screen here." />
                            </StaffRoute>
                          }
                        />
                      </Route>

                      <Route
                        path="/admin"
                        element={
                          <AdminRoute>
                            <AdminLayout />
                          </AdminRoute>
                        }
                      >
                        <Route index element={<Navigate to="dashboard" replace />} />
                        <Route path="dashboard" element={<AdminDashboard />} />
                        <Route path="products" element={<AdminProducts />} />
                        <Route path="products/new" element={<ProductForm />} />
                        <Route path="products/:id/edit" element={<ProductForm />} />
                        <Route path="orders" element={<AdminOrders />} />
                        <Route path="orders/:id" element={<AdminOrderDetail />} />
                        <Route path="categories" element={<AdminCategories />} />
                        <Route path="customers" element={<AdminCustomers />} />
                        <Route path="coupons" element={<AdminCoupons />} />
                        <Route path="fraud" element={<AdminFraud />} />
                        <Route path="analytics" element={<AdminAnalytics />} />
                        <Route path="store-settings" element={<AdminStoreSettings />} />
                      <Route path="staff" element={<StaffManagement />} />
                      </Route>

            {/* Catch-all: unknown storefront paths → custom 404 (noIndex in NotFound) */}
            <Route path="*" element={<NotFound />} />
          </Routes>
        </Suspense>
        </ErrorBoundary>
      </main>



      {!isAdmin && (
        <Suspense fallback={<footer className="site-chrome-placeholder site-chrome-placeholder--footer" aria-hidden />}>
          <Footer />
        </Suspense>
      )}
    </div>
  );
}

function App() {
  return (
    <HelmetProvider>
      <AuthProvider>
        <DeliveryLocationProvider>
          <WishlistProvider>
            <CartProvider>
              <Router>
                <StaffAuthProvider>
                  <ScrollToTop />
                  <AppShell />
                </StaffAuthProvider>
              </Router>
            </CartProvider>
          </WishlistProvider>
        </DeliveryLocationProvider>
      </AuthProvider>
    </HelmetProvider>
  );
}

export default App;
