import React, { useEffect, useState } from 'react';
import { Toaster, toast as hotToast } from 'react-hot-toast';

const toastBase =
  '!rounded-lg !px-4 !py-3 !text-sm !font-medium !shadow-lg !max-w-[min(100vw-2rem,24rem)]';

function useMobileViewport() {
  const [isMobile, setIsMobile] = useState(() =>
    typeof window !== 'undefined' ? window.matchMedia('(max-width: 767px)').matches : false
  );

  useEffect(() => {
    const mq = window.matchMedia('(max-width: 767px)');
    const sync = () => setIsMobile(mq.matches);
    sync();
    mq.addEventListener('change', sync);
    return () => mq.removeEventListener('change', sync);
  }, []);

  return isMobile;
}

/**
 * App-level toast host — import once in `App.js` (replaces raw `<Toaster />`).
 * Mobile: bottom-center above chat FAB — less intrusive than top overlays.
 */
export function AppToaster() {
  const isMobile = useMobileViewport();

  return (
    <Toaster
      position={isMobile ? 'bottom-center' : 'top-right'}
      containerClassName={
        isMobile
          ? '!bottom-[calc(4.75rem+env(safe-area-inset-bottom,0px))] !left-1/2 !right-auto !top-auto !-translate-x-1/2 !px-4'
          : '!top-4 !right-4 sm:!top-6 sm:!right-6'
      }
      toastOptions={{
        duration: 4000,
        className: `${toastBase} !bg-rozana-navy !text-white`,
        style: {},
        success: {
          duration: 3500,
          iconTheme: {
            primary: '#16A34A',
            secondary: '#ffffff',
          },
          className: `${toastBase} !bg-rozana-navy !text-white`,
        },
        error: {
          duration: 5000,
          iconTheme: {
            primary: '#F97316',
            secondary: '#ffffff',
          },
          className: `${toastBase} !bg-rozana-navy !text-white`,
        },
        loading: {
          className: `${toastBase} !bg-rozana-navy-deep !text-white`,
        },
      }}
    />
  );
}

/** Re-export so callers can use `import { toast } from './components/Toast'` */
export const toast = hotToast;

export default AppToaster;
